mapper.select:
SELECT batch_key, environment,
       CAST(JSON_UNQUOTE(JSON_EXTRACT(plan_json, '$.channelCount')) AS UNSIGNED) AS channelCount,
       CAST(JSON_UNQUOTE(JSON_EXTRACT(plan_json, '$.rateCount')) AS UNSIGNED) AS rateCount
FROM mig_channel_increment_batch
WHERE environment = #{environment} AND state = 'applied'
  AND source_uuid = #{sourceUuid} AND target_uuid = #{targetUuid}
  AND source_schema = #{sourceSchema} AND target_schema = #{targetSchema}
  AND operator_id = #{operatorId} AND plan_hash = #{planHash}
  AND JSON_EXTRACT(plan_json, '$.selectedIds') = CAST(#{selectedJson} AS JSON)
ORDER BY applied_at DESC LIMIT 1

mapper.update:
UPDATE mig_asset_job SET state = #{state}, plan_hash = #{planHash},
    source_count = #{sourceCount}, total = #{total}, completed = #{completed},
    isolated = #{isolated}, duplicates = #{duplicates}, error = #{error},
    source_hash = #{sourceHash}, channel_hash = #{channelHash}
WHERE id = #{id}

mapper.select:
SELECT * FROM mig_asset_item WHERE job_id = #{jobId} AND id > #{afterId}
AND state = #{state}
ORDER BY id LIMIT 250

mapper.update:
UPDATE mig_asset_item SET state = 'DONE',
    target_id = CASE id
    WHEN #{item.id} THEN #{item.targetId}
    END,
    after_json = CASE id
    WHEN #{item.id} THEN #{item.afterJson}
    END
WHERE id IN
#{item.id}
